style.css:
html, body {
    background: #0b141b !important;
    color: #c7d5e0 !important;
}

[data-testid="game-card"] {
    background: #16202d !important;
    border-radius: 6px !important;
    transition: all 0.2s ease !important;
}

[data-testid="game-card"]:hover {
    transform: scale(1.05) !important;
    box-shadow: 0 0 15px rgba(0, 173, 238, 0.6) !important;
}

header {
    background: linear-gradient(to right, #171a21, #1b2838) !important;
    border-bottom: 1px solid #2a475e !important;
}

h1, h2, h3 {
    color: #ffffff !important;
}

a {
    color: #66c0f4 !important;
}

img {
    border-radius: 4px;
}
